    'query_var' => true,
    'show_admin_column' => true,
    'show_ui' => true,
    'show_tagcloud' => false,
    'meta_box_cb' => 'my_custom_post_type_with_gallery',
  )
);

// Fonction personnalisée pour enregistrer et afficher le champ personnalisé
function my_custom_post_type_with_gallery( $post ) {
  wp_nonce_field( basename( __FILE__ ), 'my_custom_post_type_with_gallery' );

  // Création du champ personnalisé de galerie
  echo '<label for="my_custom_post_type_gallery">' . Esc_html__( 'Galerie', 'text-domain' ) .'</label><br>';
  echo '<input type="text" id="my_custom_post_type_gallery" name="my_custom_post_type_gallery" value="' . Esc_attr( get_post_meta( $post->ID, 'my_custom_post_type_gallery', true ) ) . '">';
}

// Enregistrement des métadonnées personnalisées de champ
function save_my_custom_post_type_with_gallery( $post_id ) {
  if ( !isset( $_POST['my_custom_post_type_with_gallery'] ) || !wp_verify_nonce( sanitize_text_field( $_POST['my_custom_post_type_with_gallery'] ), basename( __FILE__ ) ) ) {
    return $post_id;
  }

  if ( isset( $_POST['my_custom_post_type_gallery'] ) ) {
    update_post_meta( $post_id, 'my_custom_post_type_gallery', sanitize_text_field( $_POST['my_custom_post_type_gallery'] ) );
  }
}
add_action( 'save_post', 'save_my_custom_post_type_with_gallery' );
