### Exemple d'identification d'une animation de rotation sur des objets

Pour identifier les animations de rotation d'un objet glTF dans votre application, vous pouvez utiliser les propriétés suivantes :

- L'accèsseur contenant les indices des matériaux (`materialIndices`) de vos objets.
- Les accesseurs contenant les matrices de rotation (quaternions ou matrices de rotation en fonction de votre glTF).

Voici une fonction JavaScript qui extrait les noms des animations de rotation en fonction de ces propriétés :

```javascript
function getRotationAnimationNames(gltf) {
  const animationNames = [];

  // Récupérez les accesseurs de rotation pour votre objet (ici supposant que la rotation est stockée sous forme de quaternion)
  const quaternionsAccessor = gltf.accessors.find(accessor =>
    accessor.name === 'quaternions' &&
    accessor.type === 2 // type 2 correspond aux quaternions en format de tableau
  );

  const indicesAccessor = gltf.accessors.find(accessor =>
    accessor.name === 'materialIndices'
  );

  gltf.meshes.forEach(mesh => {
    const meshAnimations = mesh.animations || [];

    // Sélectionnez les animations affectant les rotations
    const rotationAnimations = meshAnimations.filter(animation =>
      animation.channels.some(channel =>
        channel.target === indicesAccessor.bufferView && // vérification de l'accèsseur des indices de matériaux pour les rotations
        channel.samplerIndex === 0 && // vérification de l'utilisation d'un seul échantillon (justifié ici pour simplifier le code en prenant en compte le cas d'une animation de rotation sur des objets communs)
        channel.targetAccessor === quaternionsAccessor.index // vérification de l'accèsseur des quaternions pour les rotations
      )
    );

    // Extrayez les noms des animations de rotation pour cet objet
    rotationAnimations.forEach(animation => {
      const animationName = `Rotation - ${mesh.name}`;
      const channel = animation.channels.find(channel => channel.target === indicesAccessor.bufferView && channel.samplerIndex === 0 && channel.targetAccessor === quaternionsAccessor.index);
      const values = new Float32Array(gltf.buffer, quaternionsAccessor.byteOffset + channel.start + channel.input.bufferView * gltf.buffer BYTE_LENGTH);
      const magnitudes = values.map(quaternion => Math.sqrt(quaternion[0] * quaternion[0] + quaternion[1] * quaternion[1] + quaternion[2] * quaternion[2] + quaternion[3] * quaternion[3]));

      // Conserve uniquement les animations ayant un écart type non-nul des magnitudes des quaternions (pour filtrer éventuellement des animations n'étant pas de rotation autour d'un axe unique)
      if (magnitudeStdDeviation(magnitudes) !== 0) {
        animationNames.push(animationName);
      }
    });
  });

  return animationNames;
}

// Fonction pour calculer l'écart-type (1ère valeur standard) des éléments d'un tableau de nombres
function magnitudeStdDeviation(numbers) {
  const avg = numbers.reduce((accumulator, currentValue) => accumulator + currentValue) / numbers.length;
  const variance = numbers.reduce((accumulator, currentValue) => accumulator + (currentValue - avg) ** 2) / numbers.length;
  return Math.sqrt(variance);
