/**
 * Fonction de sélection des caractéristiques (features) les plus importantes en tenant compte de la diversité de l'ensemble de données
 *
 * @param data         DataFrame scala avec les caractéristiques
 * @param missingEnc  Encodage de valeur de manque pour chaque caractéristique
 * @param weighting   Fournir une fonction de pondération pour chaque observation (notamment pour répartition de poids ou bootstrap)
 * @param granularity Nombre de niveaux de granularité spatiale et temporelle à prendre en compte
 * @return Une liste de 5 caractéristiques les plus importantes pour l'ensemble de données selon un ordre décroissant de coefficients de corrélation
 */
def featureSelection(data: DataFrame,
                      missingEnc: Map[String, Any], // encodage de valeur de manque pour chaque caractéristique
                      weighting: DataFrame => Seq[Double], // Fonction pour calculer des poids de sélection probabiliste pour chaque enregistrement
                      granularity: Int): List[String] = {

  // 1. Traitement des données manquantes
  val dataWithNA: DataFrame = data.na.fill(missingEnc)

  // 2. Calcul des statistiques de base sur chaque variable
