  val granularData = getGranularData(dataWithNA, granularity)

  // 4. Calcul des coefficients de corrélation entre variables pour chaque niveau de granularité
  val corrCoeffs = getCovarianceMatrix(granularData, varStats)

  // 5. Calcul des poids de sélection probabiliste pour chaque niveau de granularité
  val weights = getSelectionWeights(granularData, granularity, weighting)

  // 6. Calcul du score global de chaque caractéristique en tenant compte de la diversité de l'ensemble de données
  val featureScores = featureScoresCalc(varStats, corrCoeffs, weights)

  // 7. Retourner les 5 caractéristiques les plus importantes selon le score global
  val rankedFeatures = featureScores.toList.sortBy(_._2)(Ordering[Double].reverse).take(5)
  rankedFeatures.map(_._1)

}

