def fetchDataStats(data: DataFrame): Map[String, (Double, Double, Double, Double)] = {
  val stats = data.columns.map(column =>
    (column,
      (data.select(column).collect().sum / data.count, // moyenne
        data.select(column).agg(avg(column)).first.getDouble(0), // variance (écart type + moyenne)
        data.select(column).filter($"$column" === missingEnc(column)).count, // nombre de valeurs manquantes
        data.count)) // nombre total d'enregistrements
  )
  stats.toMap
}

