def getGranularData(data: DataFrame, granularity: Int): List[DataFrame] = {
  val (groups, groupCounts) = data.groupBy($(granularityCols)).count().rdd.take(10) // exemple de nombre maximum de groupes à traiter en tant que sous-ensembles
  groups.map { case (key, count) =>
    data.filter($(granularityCols).isin(key: _*))
  }.toList
}

// 4a. Calcul des coefficients de corrélation pour chaque niveau de granularité
def getCovarianceMatrix(granularData: List[DataFrame], varStats: Map[String, (Double, Double, Double, Double)]): List[List[Double]] = {
  val covMatrices = granularData.map { granularDF =>
    val features = granularDF.columns.toList

    val corrMat = corr(features, features, "pearson").toArray.map { case (_, row) => row.toArray }
    corrMat
  }
  covMatrices
}

// 5a. Calcul du score global de chaque caractéristique en tenant compte de la diversité de l'ensemble de données
def featureScoresCalc(varStats: Map[String, (Double, Double, Double, Double)], corrCoeffs: List[List[Double]], weights: List[List[Double]]): List[(String, Double)] = {
  val featureNames = varStats.keys.toList

  val covAdj = weights.map { weight =>
    corrCoeffs.map { row =>
      varStats.map { case (feature, (mean, variance, missingCount, totalCount)) =>
        val covariance = row(featureNames.indexOf(feature))
        val covarianceAdj = covariance * weight(featureNames.indexOf(feature))
        (feature, covarianceAdj)
      }.toList
    }.transpose
  }

  val featureScores = covAdj.map { covMatrix =>
    featureNames.map { feature =>
      val adjCov = covMatrix(featureNames.indexOf(feature)).sum / 10 // moyenne de la matrice de covariances ajustée par poids
      val MissingAdjust = Math.sqrt(
        (totalCount / (totalCount - missingCount)) * pow(variance / (totalCount - missingCount), 2) + pow(adjCov, 2))
      ((adjCov / MissingAdjust), feature)
    }
  }.flatten

  featureScores.sortBy(_._1)(Ordering[Double].reverse)

}

// 5b. Calcul des poids de sélection probabiliste pour chaque niveau de granularité
def getSelectionWeights(granularData: List[DataFrame], granularity: Int, weighting: DataFrame => Seq[Double]): List[List[Double]] = {
  val weightFunc = weighting(granularData.head)

  // Exemple de répartition de poids en utilisant une distribution Beta pour construire les poids par observation
  // (mécanisme relativement répandu dans la communauté de machine learning pour un échantillonnage stratifié)
  val betaDistBeta = new BetaDistribution(1, 1, RandomUtils.getRandom()) // valeur de biais neutre
  val betaDistAlpha = new BetaDistribution(betaDistBeta.sample(), betaDistBeta.sample(), RandomUtils.getRandom())

  val weights = granularData.map { granularDF =>
    val (groupKey, groupCount) = granularDF.groupBy($(granularityCols)).count().head
    val groupWeights = weighting(granularDF).map { weight =>
      // Beta distribution to generate weights for this group
      betaDistAlpha.sample() * weight + (1 - betaDistAlpha.sample()) * weightFunc(groupKey)
    }
    // renormalising weights to ensure they sum to 1.
    groupWeights.map(weight => weight / groupWeights.sum.toDouble)
  }

  weights
}

