```python
flowers = ["Lilac", "Daisy", "Marigold", "Chrysanthemum"]
categories = {}

for flower in flowers:
    category_key = None
    for category, prefix in {"Lilac": "Li", "Daisy": "Da", "Marigold": "Ma", "Chrysanthemum": "Ch"}.items():
        if flower.startswith(prefix):
