     return (prototype: any, method: string | symbol, descriptor: PropertyDescriptor) => {
       const originalMethod = descriptor.value;
       const methods: Method[] = Reflect.getMetadata(
         'methodsKey',
         prototype,
         method
       ) || [];
       const metadata: { path: string; methods: Method[] } = Reflect.getMetadata(
         'swaggerMetadataKey',
         prototype.constructor
       ) || {
         path: '/',
         methods: [],
       };

