         'swaggerMetadataKey',
         { ...metadata, methods: [...metadata.methods, { path, method, operationId: method.split(/\W+/).pop(), parameters: [] }] },
         prototype.constructor
       );

       Reflect.defineMetadata(
         'methodsKey',
         [...methods, { path, method }],
         prototype,
         method
       );

       descriptor.value = function (...args: any[]) {
         return originalMethod.apply(this, args);
       };

       return descriptor;
     };
   }
