Vous pouvez créer une règle personnalisée ESLint pour Vue.js en suivant les étapes ci-dessous :

1. Créez un fichier `.eslintrc.js` à la racine de votre projet (ou dans un sous-dossier `.eslintrc`).

2. Ajoutez l'extension `eslint-plugin-vue` dans les dépendances de votre projet en exécutant la commande `npm install --save-dev eslint-plugin-vue` (ou `yarn add -D eslint-plugin-vue`).

3. Ajoutez la configuration suivante à votre fichier `.eslintrc.js` :

```javascript
module.exports = {
  plugins: ['vue'],
  rules: {
    'vue/no-changing-key-value-in-hooks': 'error',
    'vue/methods-mutation-in-lifecycle-hooks': 'error'
  }
};
```

La première règle `vue/no-changing-key-value-in-hooks` vérifiera si les méthodes de cycle de vie (`beforeUpdate`, `updated`, etc.) n'ont pas modifié des propriétés internes au composant. Si c'est le cas, ESLint générera une erreur.

La deuxième règle personnalisée `vue/methods-mutation-in-lifecycle-hooks` vérifiera si les méthodes appelées au sein des méthodes de cycle de vie n'ont pas modifié des propriétés internes au composant. Elle sera créée en tant que plugin personnalisé.

4. Créez un nouveau fichier `eslint-plugin-vue/lib/rules/` appelé `methods-mutation-in-lifecycle-hooks.js`.

5. Définissez la règle dans ce fichier :

```javascript
export default {
  meta: {
    docs: { description: 'Disallow mutating internal component state from lifecycle hooks' },
    fixable: null,
    type: 'problem',
    schema: [],
  },

  create: function(context) {

    function isLifecycleMethod(node) {
      return [
        'beforeCreate',
        'created',
        'beforeMount',
        'mounted',
        'beforeUpdate',
        'updated',
        'activated',
        'deactivated',
        'beforeDestroy',
        'destroyed',
      ].includes(node.method.name);
    }

    function getCalledMethod(node) {
      return node.arguments.reduce((acc, arg) => {
        if (isMethodCallExpression(arg)) {
          return getCalledMethod(arg.callee);
        }
        return acc;
      }, null);
    }

    function isMethodCallExpression(node) {
      return (
        node.type === 'CallExpression' &&
        node.callee.type === 'MemberExpression' &&
        node.callee.object.type === 'ThisExpression'
      );
    }

    function isMutatingMethod(method) {
      if (method.params.length > 1 || !method.params[0].type.includes('Identifier')) {
        return true;
      }

      const property = method.params[0].name;

      if (
        ['data', 'props', 'computed'].includes(property) ||
        Vue.prototype[`${property}`].set
      ) {
        return true;
      }

      return false;
    }

    return {
      MemberExpression: function(node) {
        if (!isLifecycleMethod(node.object)) {
          return;
        }

        const calledMethod = getCalledMethod(node.property);

        if (calledMethod && isMutatingMethod(calledMethod)) {
          context.report({
            node,
            message: `Method ${calledMethod.name} modifies internal component state inside lifecycle hook ${node.object.method.name}.`,
          });
        }
      },
    };
  },
};
```

Cette règle vérifie les appels de méthodes dans les expressions de cet objet (`MemberExpression`), appelées depuis des méthodes de cycle de vie. Si la méthode appelée modifie une propriété internaute au composant (data, props, computed, une propriété avec un setter) alors une erreur est générée.

6. Ajoutez la règle au plugin `eslint-plugin-vue` en rajoutant la ligne suivante dans le fichier `eslint-plugin-vue/package.json`, juste après la définition de l'array `rules`:

```json
"overrides": [
  {
    "files": ["*.vue"],
    "rules": {
      "vue/methods-mutation-in-lifecycle-hooks": "error"
    }
  }
