  // S'applique uniquement aux hooks de cycle de vie des composants Vue.js
  visitor: {
    MethodDefinition(path, state) {
      const { node } {
        // A la rencontre d'une méthode dans un hook de cycle de vie
        if (!path.parentPath.isFunctionExpression() && !path.parentPath.isArrowFunctionExpression()) {
          return;
        }

        const { method, key } = node;
