  meta: {
    type: 'problem',
    docs: {
      description: 'Disallow lifecycle hooks with methods changing internal state',
      category: 'Vue.js',
      recommended: true,
    },
    fixable: 'code', // indique que cette règle peut être corrigée automatiquement

    messages: {
      noChangingInternalState: 'Lifecycle hook {{hookName}} cannot change internal state',
      noChangingInternalStateMethodCall:
        'Method {{methodName}} called from lifecycle hook {{hookName}} changes internal state',
    },
  },

  create(context) {
    return {
      // fonction handleLifecycleHook appelée pour chaque hook de cycle de vie
      'Vue/functional-component'() {},
      // définition et vérification des hooks de cycle de vie
      LifecycleHooks: LifecycleHooks.forEach((hookName) => {
        // fonction handleLifecycleHook appelée pour chaque hook de cycle de vie
        context.registererule(`vue/no-changing-internal-state-${hookName}`, {
          meta: {
            // On distingue cette règle pour chaque hook de cycle de vie avec le nom du hook
            inherits: false,
            docs: {
              description: `Disallows using methods that change the internal state in ${hookName} lifecycle hook`,
              category: 'Vue.js',
            },
            fixable: 'code',
            messages,
          },

          createnode(context) {
            // retourne une fonction de visiteur pour chaque expression dans le Hook de cycle de vie
            return {
              CallExpression(node) {
                // vérifier si la méthode appelée modifie l'état interne
                const methodName = node.callee.property?.name;
                if (METHODS_TO_WATCH.includes(methodName) && this.isChangingInternalState(methodName)) {
