                    node,
                    messageId: methodName === 'this.$forceUpdate'
                      ? 'noChangingInternalState'
                      : 'noChangingInternalStateMethodCall',
                    data: { hookName, methodName },
                    fix(fixer) {
                      // voici une simple implémentation de correction pour faciliter l'auto-correction
                      // cette implémentation peut être améliorée en fonction des cas, cependant
                      // elle fonctionne pour la plupart des cas courants
                      const methodsToRemove = getMethodsToReplaceInNode(node);
                      return methodsToRemove.reduce((acc, methodToRemove) => {
                        const newNode = fixer.removeRange([
                          methodToRemove.range[0],
                          methodToRemove.range[1],
                        ]);
                        return acc.concat(newNode);
                      }, []);
                    },
                  });
                }
              },
            };
          },
        });
      }),
    };
  },

  // Fonctions utilisées pour vérifier si la méthode appelée modifie l'état interne
  METHODS_TO_WATCH: [
    '$emit',
    '$forceUpdate',
    '$nextTick',
    '$emitEvent',
    '$dispatch',
    '$on',
    '$once',
    '$off',
    '$watch',
    '$mount',
    '$destroy',
  ],

  isChangingInternalState(methodName) {
    if (
      methodName === '$forceUpdate' ||
     ObjectName.hasOwnProperties(Object.create(null), methodName)
    ) {
      return true;
    }
    return false;
  },

  getMethodsToReplaceInNode(node) {
    const methodsToRemove = [];
    node.arguments.forEach((arg) => {
      if (arg.type === 'ObjectExpression') {
        arg.properties.forEach((prop) => {
          if (
            prop.type === 'Property' &&
            prop.key.type === 'Identifier' &&
            prop.key.name === 'handler'
          ) {
            prop.value.body.body.forEach((methodCall) => {
              if (
                methodCall.type === 'CallExpression' &&
                METHODS_TO_WATCH.includes(methodCall.callee.property?.name)
              ) {
                methodsToRemove.push(methodCall);
              }
            });
          }
        });
      } else if (arg.type === 'ArrayExpression') {
        arg.elements.forEach((elem) => {
          if (elem.type === 'ObjectExpression' && elem.properties.length > 0) {
            elem.properties.forEach((prop) => {
              if (
                prop.type === 'Property' &&
                prop.key.type === 'Identifier' &&
                prop.key.name === 'handler'
              ) {
                (prop.value.body.body || []).forEach((methodCall) => {
                  if (
                    methodCall.type === 'CallExpression' &&
                    METHODS_TO_WATCH.includes(methodCall.callee.property?.name)
                  ) {
                    methodsToRemove.push(methodCall);
                  }
                });
              }
            });
          }
        });
      }
    });
    return methodsToRemove;
  },
});
